changeSet.sql:
ALTER TABLE notification_outbox DROP CONSTRAINT ck_notification_status;
ALTER TABLE notification_outbox ADD CONSTRAINT ck_notification_status
    CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED', 'SUPPRESSED'));

rollback.sql:
DELETE FROM notification_outbox WHERE status = 'SUPPRESSED';
ALTER TABLE notification_outbox DROP CONSTRAINT ck_notification_status;
ALTER TABLE notification_outbox ADD CONSTRAINT ck_notification_status
    CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED'));
